import { useState, useEffect } from 'react';
import InvoiceTable from './InvoiceTable';
import mockData from './mockData';

export default function App() {
  const [sortedInvoices, setSortedInvoices] = useState(mockData);
  const [sortConfig, setSortConfig] = useState<{ key: string | null; direction: 'ascending' | 'descending' | null }>({
    key: null,
    direction: null,
  });

  const handleSort = (key: string) => {
    let direction: 'ascending' | 'descending' = 'ascending';
    if (sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });

    const sorted = [...sortedInvoices].sort((a, b) => {
      if (a[key] < b[key]) return direction === 'ascending' ? -1 : 1;
      if (a[key] > b[key]) return direction === 'ascending' ?  1 : -1;
      return 0;
    });
    setSortedInvoices(sorted);
  };

  return (
    <div className="container mx-auto p-4 max-w-4xl">
      <h1 className="text-2xl font-semibold mb-6 text-gray-800">Invoices</h1>
      <InvoiceTable 
        invoices={sortedInvoices} 
        onSort={handleSort} 
        sortConfig={sortConfig} 
      />
    </div>
  );
}
