### InvoiceTable.tsx
```tsx
import React from 'react';
import { mockData } from '../mockData';

type Invoice = {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: 'paid' | 'pending' | 'overdue';
};

type Props = {
  invoices: Invoice[];
  onSort: (key: string) => void;
  sortConfig: { key: string | null; direction: 'ascending' | 'descending' | null };
};

export default function InvoiceTable({ invoices, onSort, sortConfig }: Props) {
  const statusColors = {
    paid: 'bg-green-500',
    pending: 'bg-yellow-500',
    overdue: 'bg-red-500',
  };

  const totalAmount = invoices.reduce((sum, invoice) => sum + invoice.amount, 0);

  const getSortIcon = (key: string) => {
    if (sortConfig.key === key) {
      return sortConfig.direction === 'ascending' ? '↑' : '↓';
    }
    return '';
  };

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full border-collapse border border-gray-300 rounded-lg overflow-hidden">
        <thead className="bg-gray-50 text-gray-700">
          <tr>
            <th 
              className="border border-gray-200 px-4 py-3 text-left text-sm font-medium cursor-pointer hover:bg-gray-100"
              onClick={() => onSort('number')}
            >
              Number
              {getSortIcon('number')}
            </th>
            <th 
              className="border border-gray-200 px-4 py-3 text-left text-sm font-medium cursor-pointer hover:bg-gray-100"
              onClick={() => onSort('customer')}
            >
              Customer
              {getSortIcon('customer')}
            </th>
            <th 
              className="border border-gray-200 px-4 py-3 text-left text-sm font-medium cursor-pointer hover:bg-gray-100"
              onClick={() => onSort('amount')}
            >
              Amount
              {getSortIcon('amount')}
            </th>
            <th 
              className="border border-gray-200 px-4 py-3 text-left text-sm font-medium cursor-pointer hover:bg-gray-100"
              onClick={() => onSort('status')}
            >
              Status
              {getSortIcon('status')}
            </th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((invoice) => (
            <tr key={invoice.id} className="border-t border-gray-100 hover:bg-gray-50 transition-colors">
              <td className="border border-gray-200 px-4 py-3 text-sm font-medium">{invoice.number}</td>
              <td className="border border-gray-200 px-4 py-3 text-sm">{invoice.customer}</td>
              <td className="border border-gray-200 px-4 py-3 text-sm font-semibold">${invoice.amount.toFixed(2)}</td>
              <td className="border border-gray-200 px-4 py-3 text-sm">
                <span className={`inline-block w-24 text-xs font-medium rounded-full px-2 py-1 ${statusColors[invoice.status]}`}>
                  {invoice.status}
                </span>
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot className="bg-gray-50 border-t border-gray-200">
          <tr>
            <td colSpan={3} className="border border-gray-200 px-4 py-3 text-sm font-bold text-gray-700 text-right">
              Total:
            </td>
            <td className="border border-gray-200 px-4 py-3 text-sm font-bold text-gray-700">
              ${totalAmount.toFixed(2)}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}
